type criteriaFactsDoc struct{ Facts json.RawMessage `json:"facts"` }

func criteriaFactsFromValue(raw interface{}) (ids []string, issues []string) {
    list, ok := raw.([]interface{})
    if !ok { return nil, []string{"facts must be a JSON array of fact ids (strings)"} }
    seen := map[string]bool{}
    for i, item := range list {
        s, ok := item.(string); if !ok { issues = append(issues, fmt.Sprintf("facts[%d] is not a string", i)); continue }
        s = strings.TrimSpace(s)
        if s == "" { issues = append(issues, ...); continue }
        if seen[s] { issues = append(issues, ..."declared twice"...); continue }
        seen[s] = true; ids = append(ids, s)
    }
    return ids, issues
}

func parseCriteriaFacts(criteria string) (ids []string, issues []string) {
    if strings.TrimSpace(criteria) == "" { return nil, nil }   // fail-open
    var doc criteriaFactsDoc
    if err := json.Unmarshal([]byte(criteria), &doc); err != nil { return nil, nil }
    if len(doc.Facts) == 0 || string(doc.Facts) == "null" { return nil, nil }
    var raw interface{}
    if err := json.Unmarshal(doc.Facts, &raw); err != nil { return nil, []string{"facts is not valid JSON: " + err.Error()} }
    return criteriaFactsFromValue(raw)
}

// P11 — a fence-level `facts` declaration (criteria_facts.go) is an array of
// non-empty, unique fact ids. Read ONLY by refresh_evidence_base's fan-out,
// never by either checker, so it asserts nothing at acceptance time.
if raw, present := template["facts"]; present {
	if _, issues := criteriaFactsFromValue(raw); len(issues) > 0 {
		for _, is := range issues { v.errf("", "facts", "%s", is) }
	}
}

const factDriftIndexQuery = `
  SELECT p.id::text, p.name, COALESCE(p.url,''), COALESCE(p.build_status,''), dp.subject_key, dp.body,
         COALESCE((SELECT cc.id::text FROM page_components pc JOIN content_components cc ON cc.id = pc.component_id
                   WHERE pc.page_id = p.id AND cc.is_active AND cc.component_level = 'tool'
                     AND cc.function IN (dp.subject_key, 'tool-' || dp.subject_key)
                   ORDER BY pc.position LIMIT 1), '') AS fork_component_id
  FROM pages p JOIN doc_plans dp ON dp.subject_type='tool' AND dp.is_current
    AND (p.name = dp.subject_key OR p.name = 'tool-' || dp.subject_key OR EXISTS (...tool component...))
  WHERE p.site_id = $1 AND p.status = 'active' AND dp.body LIKE '%"facts"%'`

// baseline precedence: what the tool was last TOLD, else the previous register row, else nothing
func (b factDriftBaselines) baselineFor(factID, subjectKey string) *float64 {
    if v, ok := b.lastItem[baselineKey(factID, subjectKey)]; ok { return &v }
    if v, ok := b.previousRow[factID]; ok { return &v }
    return nil
}

